def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if len(alive) == 0:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    panic_bids = 0
    weak_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            weak_opp += 1
        if opp.get('budget', 0) >= 700:
            rich_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = prev.get('bid', 0)
            prev_bids.append(bid)
            if bid >= 90:
                panic_bids += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (25.0 - supply) / 10.0
    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.55
    if no_water >= 2:
        urgency += 1.0
    elif no_water == 1:
        urgency += 0.45

    endgame = day >= 8

    if urgency >= 1.5:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 3.0)
    elif urgency >= 1.0:
        bid = max(DAILY_SALARY * 0.78, avg_prev + 2.0, highest_prev * 0.72)
    else:
        if panic_bids >= 2 and hp >= 5 and no_water == 0:
            bid = DAILY_SALARY * (0.22 + 0.10 * scarcity)
        elif highest_prev >= 120:
            bid = DAILY_SALARY * (0.28 + 0.10 * scarcity)
        elif highest_prev >= 80:
            bid = min(highest_prev + 1.5, DAILY_SALARY * (0.72 + 0.10 * scarcity))
        elif highest_prev > 0:
            bid = max(DAILY_SALARY * (0.48 + 0.10 * scarcity), highest_prev + 1.5)
        else:
            bid = DAILY_SALARY * (0.50 + 0.12 * scarcity)

    if weak_opp >= 2 and urgency < 1.0 and hp >= 6:
        bid *= 0.88
    if rich_opp >= 2 and urgency > 0:
        bid *= 1.08
    if endgame and hp <= 4:
        bid = max(bid, DAILY_SALARY * 0.9)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = max(0.0, (7 - day) * 8.0)
    max_affordable = max(0.0, budget - reserve_floor)
    if urgency >= 1.0:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        cap = my_budget
        bid = DAILY_SALARY * 0.35
        return min(cap, bid)

    # Use only yesterday's immediate trace
    prev_bids = []
    prev_hp_after = []
    prev_no_water = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after', 0.0)))
            except Exception:
                pass
        if prev.get('status') is not None:
            # status may encode no-water; keep conservative
            pass
        prev_no_water.append(int(opp.get('no_water_days', 0)))

    # Estimate clearing pressure from yesterday
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        median_prev_bid = sorted(prev_bids)[len(prev_bids)//2]
    else:
        highest_prev_bid = 0.0
        median_prev_bid = DAILY_SALARY * 0.5

    # Supply-based aggressiveness: higher supply => can bid less
    # Convert supply to a rough water units factor
    units = supply / float(WATER_REQ)  # float
    # Normalize between MIN_SUPPLY and MAX_SUPPLY
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_factor = 0.5
    supply_factor = max(0.0, min(1.0, float(supply_factor)))

    # Base bid tuned to sit above typical strong bids but below extreme maxima
    # If others were spending heavily (highest_prev_bid near salary), we respond.
    pressure = 0.0
    if highest_prev_bid > 0:
        pressure = min(1.0, highest_prev_bid / (DAILY_SALARY * 1.2))

    # HP risk adjustment: if low HP or accumulating no-water days, bid more.
    hp_risk = 0.0
    if my_hp <= 2.0:
        hp_risk = 1.0
    elif my_hp <= 4.0:
        hp_risk = 0.6
    else:
        hp_risk = 0.2

    no_water_boost = 0.0
    if my_no_water_days >= 2:
        no_water_boost = 0.5
    elif my_no_water_days == 1:
        no_water_boost = 0.25

    # Decide aggressiveness level
    aggressiveness = 0.35 + 0.35 * pressure + 0.25 * hp_risk + no_water_boost
    aggressiveness = max(0.15, min(0.95, aggressiveness))

    # Target bid: slightly above median, scaled by aggressiveness, reduced if supply is high
    target = median_prev_bid * (0.85 + 0.3 * aggressiveness)

    # If highest_prev_bid is very high, ensure we don't undercut too much
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = max(target, DAILY_SALARY * (0.45 + 0.35 * aggressiveness))

    # Reduce when supply is abundant
    target = target * (0.85 + 0.3 * (1.0 - supply_factor))

    # Final cap by budget
    if my_budget <= 0:
        return 0.0

    # Keep some budget for future: don't spend more than a fraction unless in critical HP
    spend_cap_frac = 0.25
    if my_hp <= 2.0:
        spend_cap_frac = 0.9
    elif my_hp <= 4.0:
        spend_cap_frac = 0.55
    elif my_no_water_days >= 2:
        spend_cap_frac = 0.6

    max_bid = my_budget * spend_cap_frac
    bid = min(max_bid, target)

    # Ensure bid is non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = avg_prev * 0.95
    else:
        target_bid = DAILY_SALARY * 0.6

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    return min(my_status['budget'], max(target_bid, DAILY_SALARY * 0.45))
